  query?: string;
  // If true and query matches, return the entire document instead of just matched sections. Only meaningful when query is provided. Default: false.
  return_full?: boolean;
  // Selects Roblox Studio instance, use the list_roblox_studios tool to get available instances
  studio_id: string;
  // The full URL to fetch. Must match one of the allowed URL patterns.
  url: string;
}): Promise<CallToolResult>; };
```

